import { useState } from "react";

export function QuickEdit({
  fieldLabel = "{{fieldLabel}}",
  value: initialValue = "{{value}}",
  open: initialOpen = {{open}},
  accent = "{{accent}}",
}) {
  const [open, setOpen] = useState(initialOpen);
  const [value, setValue] = useState(initialValue);
  return (
    <div style={{ width: 260, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", position: "relative" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <span style={{ fontSize: 13, color: "#241430aa" }}>{fieldLabel}</span>
        <button type="button" onClick={() => setOpen((o) => !o)} style={{ display: "inline-flex", alignItems: "center", gap: 6, border: "1.5px solid " + (open ? accent : "transparent"), background: open ? "#FAF7F2" : "#24143010", borderRadius: 999, padding: "5px 12px", cursor: "pointer" }}>
          {value} <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden="true"><path d="M16 3l5 5-11 11H5v-5z" /></svg>
        </button>
      </div>
      {open && (
        <div style={{ marginTop: 8, padding: 10, borderRadius: 10, background: "#FAF7F2", border: "1.5px solid " + accent, boxShadow: "0 10px 22px rgba(36,20,48,.16)", display: "flex", gap: 6 }}>
          <input type="text" value={value} onChange={(e) => setValue(e.target.value)} style={{ flex: 1, padding: "7px 9px", borderRadius: 6, border: "1.5px solid #24143033", font: "inherit" }} />
          <button type="button" onClick={() => setOpen(false)} style={{ background: accent, border: "none", borderRadius: 6, padding: "6px 12px", fontWeight: 600, cursor: "pointer" }}>Done</button>
        </div>
      )}
    </div>
  );
}
